/*
 * The player's ROM in RAM: loading (milestone 3) and relocation
 * (port/dsi/PLAN.md, "ROM loading and relocation at boot").
 */

#include <nds.h>
#include <string.h>

#include "dsi.h"

// rom_relocs.s, generated by port/dsi/tools/gen_link.py.
extern const uint32_t gRomRelocAddCount;
extern const uint32_t gRomRelocSymbolCount;
extern const uint32_t gRomRelocSymbols[]; // (offset, value) pairs
extern const uint16_t gRomRelocAdds[];    // offset deltas; 0 escapes a 32-bit delta
extern const uint16_t gRomRelocAddsEnd[];

bool DsiRomLoad(void) {
    DsiLog("ROM loading comes with milestone 3\n");
    return false;
}

// Pointer words in data objects need not be word-aligned (data is 2-aligned).
static inline uint32_t LoadWord(const uint8_t* p) {
    uint32_t value;
    memcpy(&value, p, 4);
    return value;
}

static inline void StoreWord(uint8_t* p, uint32_t value) {
    memcpy(p, &value, 4);
}

bool DsiRomRelocate(void) {
    uint8_t* copy = __rom_copy;
    uint32_t size = __rom_copy_end - __rom_copy;
    uint32_t delta = (uint32_t)copy - DSI_ROM_BASE;
    uint32_t offset = 0, adds = 0;
    bool ok = true;

    for (const uint16_t* p = gRomRelocAdds; p < gRomRelocAddsEnd;) {
        uint32_t step = *p++;
        if (step == 0) {
            step = p[0] | ((uint32_t)p[1] << 16);
            p += 2;
        }
        offset += step;
        if (offset > size - 4) {
            DsiLog("relocation at 0x%06lx is outside the copy\n", (unsigned long)offset);
            return false;
        }
        StoreWord(copy + offset, LoadWord(copy + offset) + delta);
        adds++;
    }
    for (uint32_t i = 0; i < gRomRelocSymbolCount; i++) {
        StoreWord(copy + gRomRelocSymbols[2 * i], gRomRelocSymbols[2 * i + 1]);
    }
    DC_FlushRange(copy, size);
    if (adds != gRomRelocAddCount) {
        DsiLog("relocated %lu add-base words, expected %lu\n", (unsigned long)adds, (unsigned long)gRomRelocAddCount);
        ok = false;
    }
    DsiLog("relocated: %lu add-base, %lu symbol\n", (unsigned long)adds, (unsigned long)gRomRelocSymbolCount);
    return ok;
}
